// Promo background videos for the title cards. Each is encoded at the game's native
// resolution (pixel art, here 2x = 640x448) and upscaled nearest-neighbour in CSS
// (image-rendering: pixelated), so files stay small — well under Cloudflare Pages'
// 25 MiB per-file cap — and are served same-origin from /media.
//
// Each card has its own reel, generated by the engine repo's
// `python3 tools/media/hero_reels.py build --game all --out <dir>`. To refresh them,
// copy each promo-<game>.mp4 and promo-<game>.poster.webp (as promo-<game>-poster.webp)
// into public/media.
export const PROMO_VIDEO_S1 = '/media/promo-s1.mp4';
export const PROMO_VIDEO_S2 = '/media/promo-s2.mp4';
export const PROMO_VIDEO_S3K = '/media/promo-s3k.mp4';
// First-frame stand-ins shown before the video plays and under reduced motion.
export const PROMO_POSTER_S1 = '/media/promo-s1-poster.webp';
export const PROMO_POSTER_S2 = '/media/promo-s2-poster.webp';
export const PROMO_POSTER_S3K = '/media/promo-s3k-poster.webp';
